def resolve_pointer(document, pointer):
    """Resolve a JSON Pointer against a document.

    Implements RFC 6901 style pointer resolution with strict token
    unescaping and strict list index validation. Raises ValueError on
    any malformed pointer, missing key, invalid index, out-of-range
    index, or traversal into a scalar. The document is never modified.
    """
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")

    if pointer == "":
        return document

    if not pointer.startswith("/"):
        raise ValueError("non-empty pointer must start with '/'")

    value = document
    for raw_token in pointer.split("/")[1:]:
        token = _unescape_token(raw_token)

        if isinstance(value, dict):
            if token not in value:
                raise ValueError("missing key: %r" % (token,))
            value = value[token]
        elif isinstance(value, list):
            index = _parse_index(token)
            if index >= len(value):
                raise ValueError("index out of range: %r" % (token,))
            value = value[index]
        else:
            raise ValueError("cannot traverse scalar with token %r" % (token,))

    return value


def _unescape_token(token):
    """Decode ~1 -> / and ~0 -> ~ in a single left-to-right pass."""
    if "~" not in token:
        return token

    result = []
    i = 0
    length = len(token)
    while i < length:
        ch = token[i]
        if ch == "~":
            if i + 1 >= length:
                raise ValueError("trailing '~' in token: %r" % (token,))
            nxt = token[i + 1]
            if nxt == "0":
                result.append("~")
            elif nxt == "1":
                result.append("/")
            else:
                raise ValueError("invalid escape '~%s' in token: %r" % (nxt, token))
            i += 2
        else:
            result.append(ch)
            i += 1
    return "".join(result)


def _parse_index(token):
    """Parse a list index: ASCII '0' or [1-9][0-9]*."""
    if token == "0":
        return 0
    if not token:
        raise ValueError("empty list index")
    first = token[0]
    if first < "1" or first > "9":
        raise ValueError("invalid list index: %r" % (token,))
    for ch in token[1:]:
        if ch < "0" or ch > "9":
            raise ValueError("invalid list index: %r" % (token,))
    return int(token)

