    """Resolve a JSON Pointer (RFC 6901) against *document*.

    Returns the referenced value.  Raises ValueError for malformed
    pointers, missing keys, invalid/out-of-range list indices, or when
    traversal continues into a scalar.  *document* is never modified.
    """
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")

    if pointer == "":
        return document

    if not pointer.startswith("/"):
        raise ValueError("non-empty pointer must start with '/'")

    value = document
    for raw_token in pointer.split("/")[1:]:
        token = _decode_token(raw_token)

        if isinstance(value, dict):
            if token not in value:
                raise ValueError("missing key: %r" % (token,))
            value = value[token]
        elif isinstance(value, list):
            index = _parse_index(token)
            if index >= len(value):
                raise ValueError("list index out of range: %r" % (token,))
            value = value[index]
        else:
            raise ValueError(
                "cannot traverse into scalar with token %r" % (token,)
            )

    return value


