    with '/'. Tokens are split on '/', then each token is decoded once,
    left-to-right: '~1' -> '/', '~0' -> '~'. Any other '~' escape or a
    trailing '~' raises ValueError.

    Dicts are looked up by the decoded string key. Lists accept only ASCII
    indices matching 0 or [1-9][0-9]*; negatives, '+', leading zeros,
    Unicode digits and '-' are rejected. Invalid/out-of-range indices,
    missing dict keys, and traversal into scalars raise ValueError.

    The document is never modified.
    """
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")

    if pointer == "":
        return document

    if not pointer.startswith("/"):
        raise ValueError("non-empty pointer must start with '/'")

    value = document
    for raw_token in pointer.split("/")[1:]:
        token = _decode_token(raw_token)

        if isinstance(value, dict):
            if token not in value:
                raise ValueError("key not found: %r" % (token,))
            value = value[token]
        elif isinstance(value, list):
            index = _parse_index(token)
            if index >= len(value):
                raise ValueError("index out of range: %r" % (token,))
