def dependency_layers(dependencies):
    """Return parallelizable dependency layers.

    ``dependencies`` maps a task to the list of its prerequisites. Tasks that
    only appear as prerequisites are included in the graph. Duplicate
    prerequisites are counted once. The input mapping and its lists are never
    mutated.

    Each returned layer contains all remaining tasks whose prerequisites were
    all completed in earlier layers, sorted lexicographically. An empty graph
    yields ``[]``. If any connected component contains a cycle (including a
    self-loop), ``ValueError`` is raised and no partial result is returned.
    """
    # Build the node set and a normalized prerequisite map without mutating
    # the caller's data.
    nodes = set()
    prereqs = {}

    for task, deps in dependencies.items():
        nodes.add(task)
        unique_deps = set()
        for dep in deps:
            unique_deps.add(dep)
            nodes.add(dep)
        prereqs[task] = unique_deps

    for node in nodes:
        prereqs.setdefault(node, set())

    if not nodes:
        return []

    # Remaining prerequisite counts and reverse adjacency (task -> dependents).
    remaining = {node: len(prereqs[node]) for node in nodes}
    dependents = {node: [] for node in nodes}
    for task, deps in prereqs.items():
        for dep in deps:
            dependents[dep].append(task)

    layers = []
    ready = sorted(node for node in nodes if remaining[node] == 0)
    processed = 0

    while ready:
        layers.append(ready)
        processed += len(ready)
        next_ready = []
        for node in ready:
            for dependent in dependents[node]:
                remaining[dependent] -= 1
                if remaining[dependent] == 0:
                    next_ready.append(dependent)
        ready = sorted(next_ready)

    if processed != len(nodes):
        raise ValueError("dependency graph contains a cycle")

    return layers

