def dependency_layers(dependencies):
    """Return dependency layers as a list of sorted parallel batches.

    ``dependencies`` maps a task to its prerequisites. Tasks that only appear
    as prerequisites are included in the graph. Duplicate prerequisites are
    counted once. A ``ValueError`` is raised if any cycle exists (including
    self-loops). The input mapping and its lists are not modified.
    """
    # Build the node set and a normalized prerequisite map without mutating input.
    nodes = set()
    prereqs = {}

    for task, deps in dependencies.items():
        nodes.add(task)
        unique_deps = set()
        for dep in deps:
            nodes.add(dep)
            unique_deps.add(dep)
        prereqs[task] = unique_deps

    for node in nodes:
        prereqs.setdefault(node, set())

    # Remaining prerequisite counts and reverse adjacency (dependents).
    remaining = {node: len(prereqs[node]) for node in nodes}
    dependents = {node: set() for node in nodes}
    for task, deps in prereqs.items():
        for dep in deps:
            dependents[dep].add(task)

    layers = []
    ready = sorted(node for node in nodes if remaining[node] == 0)
    processed = 0

    while ready:
        layers.append(ready)
        processed += len(ready)
        next_ready = []
        for node in ready:
            for dependent in dependents[node]:
                remaining[dependent] -= 1
                if remaining[dependent] == 0:
                    next_ready.append(dependent)
        ready = sorted(next_ready)

    if processed != len(nodes):
        raise ValueError("dependency graph contains a cycle")

    return layers

